// Module 15 evidence: one real appliance installed from a package generated by the dev stack (custom-REST PSA
// against the fake PSA) and verified; the deployment is decommissioned from the Control Plane on the full page
// (typed confirmation), the appliance's banner and Removal page are captured, the host-side uninstall script
// wipes the appliance (its output is kept), the retention settings page is captured, and the record is removed.
// Usage: node scripts/screenshots-m15.mjs
import { spawn, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-15/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const hostIp = sh(`ip -4 route get 1.1.1.1 | awk '{for(i=1;i<=NF;i++) if($i=="src") print $(i+1)}'`).out;

const API_KEY = `demo-${Math.random().toString(36).slice(2, 10)}`;
const caPath = join(realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m15ca-'))), 'ca.pem');
const fake = spawn(process.execPath, [fileURLToPath(new URL('./fake-psa.mjs', import.meta.url)), hostIp, API_KEY, caPath], { stdio: ['ignore', 'pipe', 'inherit'] });
const port = await new Promise((resolve, reject) => {
  fake.stdout.on('data', (d) => { for (const line of String(d).split(/\r?\n/)) { const m = /^PORT (\d+)$/.exec(line); if (m) resolve(Number(m[1])); } });
  fake.on('exit', (code) => reject(new Error(`fake PSA exited with ${code}`)));
});

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

// 1. A real appliance under a demo license.
const client = (await api('GET', '/clients?status=active&pageSize=50')).items.find((c) => c.code !== 'CL-00001');
const services = await api('GET', `/clients/${client.id}/services`);
const instance = await api('POST', '/psa-instances', {
  clientId: client.id, providerKey: 'custom_rest', displayName: `${client.displayName} — Demo PSA ${Date.now().toString(36)}`, authMethod: 'api_key',
  config: { baseUrl: `https://${hostIp}:${port}/api`, healthPath: '/health', apiKeyHeader: 'X-API-Key', ticketsPath: '/tickets' }, enabledServiceIds: services.filter((s) => s.requiresPsa).map((s) => s.id),
});
const today = new Date().toISOString().slice(0, 10);
const demoLicense = await api('POST', '/licenses', { clientId: client.id, displayName: 'Help Desk Plus (demo)', startsAt: today, endsAt: null, maxDeployments: 2, notes: 'Created for the Module 15 walkthrough.' });
const dep = await api('POST', '/deployments', { clientId: client.id, psaInstanceId: instance.id, licenseId: demoLicense.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module15-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m15-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m15shots/${project}`;
const adminPort = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unix = (p) => sh(`wslpath -a '${p}'`).out;
const adminBase = `http://127.0.0.1:${adminPort}`;
const curl = (args) => sh(`curl -s -o /tmp/psacc-m15shots/body -w '%{http_code}' -b /tmp/psacc-m15shots/jar -c /tmp/psacc-m15shots/jar ${args}; echo; cat /tmp/psacc-m15shots/body`, 60_000).out;
const waitFor = async (fn, ms, label) => { const end = Date.now() + ms; while (Date.now() < end) { if (await fn()) return; await sleep(2000); } throw new Error(`timed out: ${label}`); };
const agentState = () => { const r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent status`, 60_000); try { return JSON.parse(r.out).state; } catch { return `? ${r.err}`; } };

try {
  let r = sh(`rm -rf /tmp/psacc-m15shots && mkdir -p /tmp/psacc-m15shots && cd /tmp/psacc-m15shots && unzip -q "${unix(join(winTmp, pkg.fileName))}" && cd ${project} && cp config/edge.env.template .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).lifecycleState === 'verified', 180_000, 'verified');
  const pw = `demo-${dep.code}-local-admin-pass`;
  curl(`-X POST --data-urlencode username=localadmin --data-urlencode password=${pw} --data-urlencode confirm=${pw} ${adminBase}/setup`);
  const token = /name="csrf" value="([^"]+)"/.exec(curl(`${adminBase}/credentials`))[1];
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode field_apiKey=${API_KEY} --data-urlencode "field_tlsCaCertificate@${unix(caPath)}" ${adminBase}/credentials`);
  if (!curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`).includes('Connection verified')) throw new Error('the appliance test did not verify');
  const sample = { deployment: dep.code, client: client.code, license: demoLicense.code, steps: [] };

  // 2. Decommission on the full page.
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await page.getByTestId('decommission-link').click();
  await page.waitForURL(/\/decommission$/);
  await page.getByTestId('decommission-reason').fill('Contract ended; the site closed on 30 September');
  await page.getByTestId('decommission-confirm').fill(dep.code);
  await page.waitForTimeout(300);
  await shot(page, '01-decommission-page');
  await page.getByTestId('decommission-submit').click();
  await page.waitForURL(/saved=decommissioned/);
  await page.waitForLoadState('networkidle');
  await shot(page, '02-overview-decommissioned');
  sample.steps.push({ step: 'decommissioned', detail: (await api('GET', `/deployments/${dep.id}`)).decommission });

  // 3. The appliance learns it from the gateway: banner, removal page, sync disabled.
  await waitFor(async () => agentState() === 'decommissioned', 120_000, 'agent decommissioned');
  const flag = () => sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-postgres sh -c 'PGPASSWORD="$(cat /run/secrets/postgres_owner_password)" psql -h 127.0.0.1 -U psa_edge_owner -d psa_edge -qtAX' <<'SQL'
SELECT count(*) FROM app_metadata WHERE key = 'service.decommissioned'
SQL`, 60_000).out.trim();
  await waitFor(async () => flag() === '1', 60_000, 'worker flag');
  sample.steps.push({ step: 'appliance', agentState: agentState() });
  const edge = await browser.newContext({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 2 });
  const ep = await edge.newPage();
  await ep.goto(`http://localhost:${adminPort}/login`);
  await ep.getByLabel('User name').fill('localadmin');
  await ep.getByLabel('Password').fill(pw);
  await ep.getByRole('button', { name: 'Sign in' }).click();
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  await ep.getByTestId('decommissioned-banner').waitFor();
  await shot(ep, '03-appliance-decommissioned-banner', false);
  await ep.goto(`http://localhost:${adminPort}/removal`, { waitUntil: 'networkidle' });
  await shot(ep, '04-appliance-removal-page');
  await ep.goto(`http://localhost:${adminPort}/sync`, { waitUntil: 'networkidle' });
  await shot(ep, '05-appliance-sync-stopped', false);
  await edge.close();

  // 4. Host-side wipe with the typed deployment ID (the refusal without it is recorded too).
  const refused = sh(`cd ${work} && scripts/uninstall.sh --wipe --confirm DEP-00000`, 120_000);
  const wipe = sh(`cd ${work} && scripts/uninstall.sh --wipe --confirm ${dep.code}`, 300_000);
  const left = sh(`docker ps -a --format '{{ .Names }}' | grep -c '^${project}-' ; docker volume ls -q | grep -c '^${project}_' ; test -e ${work}/secrets && echo secrets-present || echo secrets-gone`);
  writeFileSync(`${outDir}uninstall-sh-output.txt`, `$ scripts/uninstall.sh --wipe --confirm DEP-00000\n${refused.out}\n${refused.err}\n(exit ${refused.code})\n\n$ scripts/uninstall.sh --wipe --confirm ${dep.code}\n${wipe.out}\n${wipe.err}\n(exit ${wipe.code})\n\n$ docker ps -a | grep ${project}- ; docker volume ls | grep ${project}_ ; secrets\n${left.out}\n`);
  if (wipe.code !== 0) throw new Error(`wipe failed: ${wipe.err || wipe.out}`);
  sample.steps.push({ step: 'wiped', leftovers: left.out.split('\n') });

  // 5. Retention settings and the removal of the record.
  await page.goto(`${base}/settings/retention`, { waitUntil: 'networkidle' });
  await shot(page, '06-settings-data-retention');
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await page.getByTestId('remove-deployment').click();
  await page.getByTestId('remove-confirm').fill(dep.code);
  await page.waitForTimeout(300);
  await page.getByTestId('remove-panel').scrollIntoViewIfNeeded();
  await shot(page, '07-remove-record-inline-confirmation', false);
  await page.getByTestId('remove-submit').click();
  await page.waitForURL(/\/deployments$/);
  await page.goto(`${base}/deployments?lifecycle=decommissioned`, { waitUntil: 'networkidle' });
  await shot(page, '08-deployments-list-decommissioned-stage', false);
  await page.goto(`${base}/audit?q=${encodeURIComponent(dep.code)}`, { waitUntil: 'networkidle' });
  await shot(page, '09-audit-trail-after-removal', false);
  const audit = await api('GET', `/audit-events?targetType=deployment&targetId=${dep.id}&pageSize=50`);
  sample.steps.push({ step: 'removed', recordStatus: (await page.request.get(`${base}/api/v1/deployments/${dep.id}`)).status(), audit: audit.items.map((e) => ({ action: e.action, actor: e.actorDisplay, outcome: e.outcome })) });
  writeFileSync(`${outDir}decommission-sample.json`, JSON.stringify(sample, null, 2));
} finally {
  sh(`cd ${work} 2>/dev/null && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m15shots`);
  rmSync(winTmp, { recursive: true, force: true });
  fake.kill('SIGTERM');
  rmSync(caPath, { force: true });
  await browser.close();
}
